// Timer_WDT_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module Timer_WDT_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [15:0] c_prescale,
  input logic  c_tmr_en,
  input logic  c_ts_en,
  input logic  c_wdt_en,
  input logic [31:0] c_period,
  input logic [31:0] c_ts_base,
  input logic [15:0] c_ts_words,
  input logic [31:0] c_wdt_load,
  input logic  c_kick,
  input logic [31:0] c_count,
  input logic [15:0] c_ts_wp,
  input logic [15:0] c_ts_missed,
  input logic [31:0] c_wdt_count,
  input logic  c_wdt_reset,
  input logic  c_tmr_irq,
  input logic  c_bark,
  input logic  c_ts_err
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 15;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:14];          // model of every stored word
  logic [2:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_tmr_irq) m_set[0] = 1'b1;
    if (c_bark) m_set[1] = 1'b1;
    if (c_ts_err) m_set[2] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 10) ? PWDATA & m_be & 32'h1 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h5C0C0100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return 0;
      11: return (32'(c_count) << 0);
      12: return (32'(c_ts_wp) << 0) | (32'(c_ts_missed) << 16);
      13: return (32'(c_wdt_count) << 0);
      14: return (32'(c_wdt_reset) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][2:0] & m_w[2][2:0]))
  `SVA_INV(a_core_prescale, c_prescale == m_w[5][15:0])
  `SVA_INV(a_core_tmr_en, c_tmr_en == m_w[5][16:16])
  `SVA_INV(a_core_ts_en, c_ts_en == m_w[5][17:17])
  `SVA_INV(a_core_wdt_en, c_wdt_en == m_w[5][18:18])
  `SVA_INV(a_core_period, c_period == m_w[6][31:0])
  `SVA_INV(a_core_ts_base, c_ts_base == m_w[7][31:0])
  `SVA_INV(a_core_ts_words, c_ts_words == m_w[8][15:0])
  `SVA_INV(a_core_wdt_load, c_wdt_load == m_w[9][31:0])
  `SVA_INV(a_core_kick, c_kick == m_pulse_CMD[0])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_prescale == 16'h0 && c_tmr_en == 1'h0 && c_ts_en == 1'h0 && c_wdt_en == 1'h0 && c_period == 32'h0 && c_ts_base == 32'h0 && c_ts_words == 16'h0 && c_wdt_load == 32'h0 && c_kick == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_PERIOD, m_rd && m_map && m_idx == 6)
  `FC(wr_PERIOD, m_wr && m_map && m_idx == 6)
  `FC(rd_TS_BASE, m_rd && m_map && m_idx == 7)
  `FC(wr_TS_BASE, m_wr && m_map && m_idx == 7)
  `FC(rd_TS_WORDS, m_rd && m_map && m_idx == 8)
  `FC(wr_TS_WORDS, m_wr && m_map && m_idx == 8)
  `FC(rd_WDT_LOAD, m_rd && m_map && m_idx == 9)
  `FC(wr_WDT_LOAD, m_wr && m_map && m_idx == 9)
  `FC(rd_CMD, m_rd && m_map && m_idx == 10)
  `FC(wr_CMD, m_wr && m_map && m_idx == 10)
  `FC(rd_COUNT, m_rd && m_map && m_idx == 11)
  `FC(wr_COUNT, m_wr && m_map && m_idx == 11)
  `FC(rd_TS_STATE, m_rd && m_map && m_idx == 12)
  `FC(wr_TS_STATE, m_wr && m_map && m_idx == 12)
  `FC(rd_WDT_COUNT, m_rd && m_map && m_idx == 13)
  `FC(wr_WDT_COUNT, m_wr && m_map && m_idx == 13)
  `FC(rd_WDT_STATE, m_rd && m_map && m_idx == 14)
  `FC(wr_WDT_STATE, m_wr && m_map && m_idx == 14)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_TIMER_set, m_set[0])
  `FC(irq_TIMER_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_TIMER_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_TIMER_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_BARK_set, m_set[1])
  `FC(irq_BARK_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_BARK_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_BARK_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_TS_ERR_set, m_set[2])
  `FC(irq_TS_ERR_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_TS_ERR_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_TS_ERR_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(cmd_kick, m_pulse_CMD[0])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind Timer_WDT_apb Timer_WDT_apb_sva u_apb_sva (.*);
